mapper.select:
SELECT id, source_type, scene_code, title, content_type, biz_type, sender_user_id, recipient_scope_type, delivery_mode, total_count, success_count, fail_count, status, recalled_at, create_time, update_time, create_user, update_user FROM in_app_message
AND status = #{query.status}
AND source_type = #{query.sourceType}
AND recipient_scope_type = #{query.recipientScopeType}
AND delivery_mode = #{query.deliveryMode}
AND biz_type = #{query.bizType}
AND title LIKE CONCAT(#{query.title}, '%')
ORDER BY create_time DESC

mapper.update:
UPDATE in_app_message
SET status        = #{status},
    success_count = #{deliveredCount},
    total_count   = #{deliveredCount}
WHERE id = #{id}

UPDATE in_app_message
SET status         = 'RECALLED',
    recalled_at    = #{recalledAt},
    recall_user_id = #{recallUserId}
WHERE id = #{id}
  AND status IN ('SUCCESS', 'PARTIAL', 'NO_RECIPIENTS')
